 "content": "def transform(grid):
    """Restore cells marked 3 from the grid's horizontal/vertical symmetry."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3:
                continue
            candidates = [
                grid[r][w - 1 - c],
                grid[h - 1 - r][c],
                grid[h - 1 - r][w - 1 - c],
            ]
            values = [v for v in candidates if v != 3]
            if values:
                out[r][c] = max(set(values), key=values.count)
    return out
